// [RASTREIO 4] Lista do banco (rastreio_a_casar) vira um item por evidência, com o endereço de busca no Kommo.
// Evidência do Kommo já sabe o lead; a da Meta só tem o telefone e procura o contato pelos 8 finais
// (a busca do Kommo) para depois conferir DDD + 8 no resolve.
const cfg = $('configuracoes').first().json;
const out = [];
for (const it of $input.all()) {
  for (const r of (it.json.itens || [])) {
    let url = null;
    let tipo = null;
    if (r.lead_id) { url = `${cfg.kommo_api}/leads/${r.lead_id}?with=contacts`; tipo = 'lead'; }
    else if (r.contato_id) { url = `${cfg.kommo_api}/contacts/${r.contato_id}?with=leads`; tipo = 'contato_id'; }
    else if (r.busca_tel) { url = `${cfg.kommo_api}/contacts?query=${encodeURIComponent(r.busca_tel)}&with=leads&limit=50`; tipo = 'contato'; }
    if (!url) continue;  // o banco já grava essas como ignoradas; aqui é só a segunda trava
    out.push({ json: { ...r, busca_url: url, busca_tipo: tipo } });
  }
}
return out;

// [RASTREIO 4] Resposta da busca no Kommo vira o lead_id certo (ou o motivo de não ter achado).
// O nó HTTP anterior roda com resposta em TEXTO e sem estourar: o Kommo responde 204 sem corpo quando a
// busca não acha nada, e o parser de JSON do n8n quebra nisso. Credencial recusada, porém, ESTOURA aqui.
function corpo(j) {
  if (j.error) {
    const m = String((j.error && j.error.message) || j.error);
    if (/401|403|unauthori|forbidden|credential/i.test(m)) throw new Error('Kommo recusou a credencial: ' + m.slice(0, 200));
    if (/json|string|undefined|204|empty/i.test(m)) return null;
    throw new Error('Kommo devolveu erro: ' + m.slice(0, 200));
  }
  const st = Number(j.statusCode || 200);
  if (st === 204) return null;
  if (st === 401 || st === 403) throw new Error('Kommo recusou a credencial (HTTP ' + st + ')');
  if (st >= 400) return { __status: st };
  let b = j.body !== undefined ? j.body : j.data;
  if (typeof b === 'string') { if (!b.trim()) return null; b = JSON.parse(b); }
  return b || null;
}
function chaveTel(t) {
  let d = String(t || '').replace(/\D/g, '');
  if (d.length === 10 || d.length === 11) d = '55' + d;
  if (d.startsWith('55') && (d.length === 12 || d.length === 13)) return d.slice(2, 4) + d.slice(-8);
  return d || null;
}
const fontes = $('explode').all();
const respostas = $input.all();
if (fontes.length !== respostas.length) {
  throw new Error(`pareamento quebrado: ${fontes.length} buscas e ${respostas.length} respostas`);
}
const cfg = $('configuracoes').first().json;
const out = [];
respostas.forEach((it, i) => {
  const r = fontes[i].json;
  const b = corpo(it.json);
  let leadId = null, contatoId = r.contato_id || null, motivo = null;
  if (r.busca_tipo === 'lead') {
    if (b && b.id) { leadId = b.id; contatoId = contatoId || (((b._embedded || {}).contacts || [])[0] || {}).id || null; }
    else motivo = b && b.__status ? 'kommo_http_' + b.__status : 'lead_nao_existe';
  } else if (r.busca_tipo === 'contato_id') {
    // o Kommo disse qual contato escreveu: o lead é o mais novo dele (o filtro de funil e idade é do decide)
    const leads = (((b || {})._embedded || {}).leads || []).map((l) => l.id).sort((a, z) => z - a);
    if (b && b.id && leads.length) { leadId = leads[0]; contatoId = b.id; }
    else motivo = b && b.__status ? 'kommo_http_' + b.__status : (b && b.id ? 'contato_sem_lead' : 'contato_nao_existe');
  } else {
    const contatos = ((b || {})._embedded || {}).contacts || [];
    const casam = contatos.filter((c) => (c.custom_fields_values || [])
      .filter((f) => f.field_code === 'PHONE')
      .some((f) => (f.values || []).some((v) => chaveTel(v.value) === r.tel_chave)));
    // o lead mais novo do contato que casou; o filtro de funil e de idade é do decide
    const leads = casam.flatMap((c) => (((c._embedded || {}).leads) || []).map((l) => ({ id: l.id, contato: c.id })));
    leads.sort((a, z) => z.id - a.id);
    if (leads.length) { leadId = leads[0].id; contatoId = leads[0].contato; }
    else motivo = contatos.length ? 'telefone_nao_confere' : 'contato_nao_achado';
  }
  out.push({ json: { ...r, lead_id: leadId, contato_id: contatoId, motivo,
                     lead_url: leadId ? `${cfg.kommo_api}/leads/${leadId}` : null } });
});
return out;

// [RASTREIO 4] Decide o que gravar no lead. Regra de ouro: SÓ CAMPO VAZIO. O que o lead já tem
// (escrito pela equipe, pela IA ou por outro rastreio) não é trocado aqui; a prova completa fica no banco.
function corpo(j) {
  if (j.error) {
    const m = String((j.error && j.error.message) || j.error);
    if (/401|403|unauthori|forbidden|credential/i.test(m)) throw new Error('Kommo recusou a credencial: ' + m.slice(0, 200));
    return null;
  }
  const st = Number(j.statusCode || 200);
  if (st === 401 || st === 403) throw new Error('Kommo recusou a credencial (HTTP ' + st + ')');
  if (st >= 400 || st === 204) return null;
  let b = j.body !== undefined ? j.body : j.data;
  if (typeof b === 'string') { if (!b.trim()) return null; b = JSON.parse(b); }
  return b || null;
}
const cfg = $('configuracoes').first().json;
const fontes = $('achou lead?').all();
const respostas = $input.all();
if (fontes.length !== respostas.length) {
  throw new Error(`pareamento quebrado: ${fontes.length} leads e ${respostas.length} respostas`);
}
const out = [];
respostas.forEach((it, i) => {
  const r = fontes[i].json;
  const lead = corpo(it.json);
  const base = { evidencia_id: r.evidencia_id, lead_id: r.lead_id, contato_id: r.contato_id };
  if (!lead || !lead.id) { out.push({ json: { ...base, ok: false, motivo: 'lead_nao_lido', tem_patch: false } }); return; }

  if (cfg.pipelines && cfg.pipelines.length && !cfg.pipelines.includes(lead.pipeline_id)) {
    out.push({ json: { ...base, ok: false, motivo: 'fora_do_funil_' + lead.pipeline_id, tem_patch: false } });
    return;
  }
  // achado só pelo telefone: o lead tem de ter nascido perto da mensagem (senão é um lead antigo da pessoa)
  if (r.busca_tipo === 'contato') {
    const evid = Date.parse(r.criado_em) / 1000;
    const horas = (evid - Number(lead.created_at || 0)) / 3600;
    if (horas > (cfg.lead_max_horas_antes || 48)) {
      out.push({ json: { ...base, ok: false, motivo: 'lead_antigo', tem_patch: false } });
      return;
    }
  }

  const atuais = {};
  for (const f of (lead.custom_fields_values || [])) {
    const v = (f.values || [])[0];
    if (v && v.value !== undefined && v.value !== null && String(v.value).trim() !== '') atuais[f.field_id] = v;
  }
  const d = r.dados || {};
  const campos = [];
  const gravados = [];
  const poe = (fieldId, valor, nome) => {
    if (!fieldId || valor === undefined || valor === null || String(valor).trim() === '') return;
    if (atuais[fieldId]) return;
    campos.push({ field_id: Number(fieldId), values: [{ value: String(valor).slice(0, 250) }] });
    gravados.push(nome);
  };
  const t = cfg.campos_tracking || {};
  poe(t.UTM_SOURCE, d.utm_source, 'utm_source');
  poe(t.UTM_MEDIUM, d.utm_medium, 'utm_medium');
  poe(t.UTM_CAMPAIGN, d.utm_campaign, 'utm_campaign');
  poe(t.UTM_CONTENT, d.utm_content, 'utm_content');
  poe(t.UTM_TERM, d.utm_term, 'utm_term');
  poe(t.GCLID, d.gclid || d.gbraid || d.wbraid, 'gclid');
  poe(t.FBCLID, d.fbclid, 'fbclid');
  const extra = cfg.campos_extra || {};
  poe(extra.codigo, d.codigo, 'codigo');
  poe(extra.ad_id, d.ad_id, 'ad_id');
  poe(extra.ctwa_clid, d.ctwa_clid, 'ctwa_clid');
  poe(extra.grau, r.grau, 'grau');

  // Origem do Lead é lista: só grava se estiver vazia e se a origem tiver opção na lista
  const enumId = r.origem ? (cfg.origem_enums || {})[r.origem] : null;
  if (cfg.campo_origem_id && enumId && !atuais[cfg.campo_origem_id]) {
    campos.push({ field_id: Number(cfg.campo_origem_id), values: [{ enum_id: Number(enumId) }] });
    gravados.push('origem');
  }

  out.push({ json: { ...base, ok: true, motivo: gravados.length ? null : 'nada_vazio_para_gravar',
    gravados, tem_patch: campos.length > 0,
    patch_url: `${cfg.kommo_api}/leads/${lead.id}`,
    patch: { custom_fields_values: campos } } });
});
return out;

// [RASTREIO 4] Depois do PATCH no lead: só marca "casado" o que o Kommo aceitou.
// 401/403 estoura (o errorWorkflow avisa); outro erro volta para a fila com o motivo e tenta de novo.
const fontes = $('tem patch?').all();
const respostas = $input.all();
if (fontes.length !== respostas.length) throw new Error(`pareamento quebrado: ${fontes.length} x ${respostas.length}`);
const out = [];
respostas.forEach((it, i) => {
  const f = fontes[i].json;
  const j = it.json || {};
  let st = Number(j.statusCode || 0);
  if (j.error) {
    const m = String((j.error && j.error.message) || j.error);
    if (/401|403|unauthori|forbidden|credential/i.test(m)) throw new Error('Kommo recusou a credencial no PATCH: ' + m.slice(0, 200));
    st = st || 599;
  }
  if (st === 401 || st === 403) throw new Error('Kommo recusou a credencial no PATCH (HTTP ' + st + ')');
  const ok = st >= 200 && st < 300;
  out.push({ json: ok ? f : { ...f, ok: false, motivo: 'patch_http_' + st } });
});
return out;
